/* Shared visual language for the two browser-native RAUM Studio pages. */
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 82px; }
body { margin: 0; background: #f7f6f2; color: #273b34; font-family: Arial, Helvetica, sans-serif; font-size: 16px; line-height: 1.65; }
h1, h2, h3, p, figure, blockquote, dl, ol, ul { margin: 0; }
h1, h2 { font-family: Georgia, serif; font-weight: 400; letter-spacing: -2px; line-height: 1.06; }
h1 { font-size: 88px; }
h2 { font-size: 54px; }
h3 { font-size: 21px; line-height: 1.35; font-weight: 400; }
em { font-weight: 400; }
p + p { margin-top: 20px; }
a { color: inherit; text-decoration: none; }
a:hover { color: #a24d2c; }
button, input, select, textarea { font: inherit; }
button, summary, select { cursor: pointer; }
img { display: block; width: 100%; height: auto; }
a:focus-visible, button:focus-visible, summary:focus-visible, [tabindex]:focus-visible { outline: 2px solid #a24d2c; outline-offset: 5px; }
input:focus, select:focus, textarea:focus { outline: 2px solid #496453; outline-offset: 2px; }
section[id], figure[id] { scroll-margin-top: 90px; }
.container { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 48px; }
.eyebrow { margin-bottom: 24px; font-size: 11px; font-weight: 700; letter-spacing: 2px; line-height: 1.6; text-transform: uppercase; }
.skip-link { position: fixed; top: -100px; left: 16px; z-index: 100; padding: 12px 20px; background: #273b34; color: #fff; }
.skip-link:focus { top: 12px; }
.site-header { border-bottom: 1px solid #d7dcd2; }
.header-inner { display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 100px; }
.wordmark { display: block; font-size: 32px; font-weight: 700; letter-spacing: -1px; line-height: 1; }
.wordmark span { display: block; margin-top: 6px; font-size: 9px; letter-spacing: 5px; font-weight: 400; }
.main-nav { display: flex; gap: 32px; font-size: 13px; }
.main-nav a { padding: 9px 0; border-bottom: 1px solid transparent; }
.main-nav a:hover, .main-nav a[aria-current="page"] { border-bottom-color: #a24d2c; }
.header-contact { display: flex; gap: 18px; padding: 10px 0; border-bottom: 1px solid #273b34; font-size: 13px; }
.hero { padding-top: 72px; }
.hero-heading { display: grid; grid-template-columns: 1.5fr 1fr; align-items: end; gap: 80px; margin-bottom: 48px; }
.hero-intro { max-width: 340px; padding-bottom: 4px; font-size: 16px; }
.hero-intro p { margin-bottom: 28px; }
.text-link { display: inline-block; padding-bottom: 5px; border-bottom: 1px solid #8a9689; font-size: 13px; }
.text-link span { display: inline-block; margin-left: 24px; }
.hero-figure { position: relative; overflow: hidden; background: #d9dfce; }
.hero-figure figcaption { position: absolute; bottom: 24px; left: 24px; right: 24px; display: flex; justify-content: space-between; gap: 16px; padding: 14px 20px; background: #f7f6f2; font-size: 12px; }
.hero-figure figcaption a { font-weight: 700; }
.hero-footnote { display: flex; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid #d7dcd2; font-size: 11px; color: #6b776b; }
.section { padding-top: 112px; padding-bottom: 112px; }
.section-heading { display: grid; grid-template-columns: 1.5fr 1fr; gap: 80px; align-items: end; margin-bottom: 48px; }
.section-heading > p { max-width: 360px; color: #667365; }
.project-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.project-card { border-bottom: 1px solid #cbd2c5; padding-bottom: 28px; }
.project-image { display: block; overflow: hidden; background: #e4e5d9; }
.project-image img { height: 260px; object-fit: cover; transition: transform .45s ease; }
.project-image:hover img { transform: scale(1.04); }
.project-meta { display: flex; justify-content: space-between; gap: 12px; margin: 20px 0 10px; font-size: 10px; letter-spacing: 1px; text-transform: uppercase; color: #667365; }
.project-card h3 a { display: flex; justify-content: space-between; align-items: center; }
.project-card p { margin-top: 12px; font-size: 14px; color: #667365; }
.studio-section { padding: 100px 0; background: #e8ebdf; }
.studio-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 96px; }
.studio-layout h2 { margin-bottom: 36px; }
.studio-copy { padding-top: 36px; }
.large-copy { margin-bottom: 26px; font-family: Georgia, serif; font-size: 27px; line-height: 1.4; }
.studio-copy > p:not(.large-copy) { color: #526353; }
.studio-facts { display: flex; gap: 40px; margin-top: 40px; padding-top: 24px; border-top: 1px solid #bdc7b5; }
.studio-facts dt { font-family: Georgia, serif; font-size: 38px; line-height: 1.2; }
.studio-facts dd { margin: 8px 0 0; font-size: 11px; }
.process-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; padding: 0; list-style: none; }
.process-grid li { border-top: 1px solid #cbd2c5; padding-top: 24px; }
.step-number { display: block; margin-bottom: 36px; font-family: Georgia, serif; font-size: 36px; font-style: italic; color: #9c5639; }
.process-grid p { margin-top: 16px; font-size: 14px; color: #667365; }
.material-section { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; padding-top: 32px; padding-bottom: 72px; }
.material-figure img { background: #ddd5c6; }
.material-figure figcaption { margin-top: 12px; font-size: 11px; color: #6b776b; }
.material-copy h2 { margin-bottom: 30px; }
.material-copy > p:not(.eyebrow) { color: #526353; }
.material-copy .text-link { margin-top: 28px; }
.quote-section { padding-top: 80px; padding-bottom: 80px; text-align: center; border-top: 1px solid #d7dcd2; border-bottom: 1px solid #d7dcd2; }
.quote-section p { font-family: Georgia, serif; font-size: 60px; line-height: 1.12; letter-spacing: -1px; }
.quote-section footer { margin-top: 28px; font-size: 11px; letter-spacing: 1px; text-transform: uppercase; }
.faq-layout { display: grid; grid-template-columns: 1fr 1.2fr; gap: 100px; }
.faq-layout h2 { margin-bottom: 24px; }
.faq-layout > div > p:not(.eyebrow) { max-width: 300px; font-size: 14px; color: #667365; }
.faq-list details { border-bottom: 1px solid #cbd2c5; }
.faq-list details:first-child { border-top: 1px solid #cbd2c5; }
.faq-list summary { padding: 23px 0; font-size: 16px; }
.faq-list summary:hover { color: #a24d2c; }
.details-body { padding: 0 28px 24px 20px; color: #667365; font-size: 14px; }
.contact-band { padding: 80px 0; background: #273b34; color: #f7f6f2; }
.contact-layout { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.contact-layout h2 { font-size: 72px; margin-bottom: 24px; }
.contact-layout p:not(.eyebrow) { font-size: 14px; color: #c9d1c6; }
.button { display: inline-flex; align-items: center; justify-content: space-between; gap: 32px; padding: 16px 24px; border: 1px solid #273b34; border-radius: 0; background: #273b34; color: #f7f6f2; font-size: 13px; line-height: 1.5; transition: background-color .2s ease, transform .2s ease, box-shadow .2s ease; }
.button:hover { background: #496453; border-color: #496453; color: #fff; transform: translateY(-2px); box-shadow: 0 6px 16px rgb(39 59 52 / 12%); }
.button-light { border-color: #f7f6f2; background: #f7f6f2; color: #273b34; }
.button-light:hover { background: #e8ebdf; border-color: #e8ebdf; color: #273b34; }
.button-outline { background: transparent; color: #273b34; }
.site-footer { padding: 64px 0 24px; }
.footer-top { display: grid; grid-template-columns: 1fr 1.5fr 1fr; gap: 40px; align-items: start; padding-bottom: 48px; }
.footer-top p { font-size: 13px; color: #667365; }
.footer-top nav { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; font-size: 13px; }
.footer-bottom { display: flex; justify-content: space-between; gap: 24px; padding-top: 20px; border-top: 1px solid #d7dcd2; font-size: 10px; color: #667365; }
.project-hero { padding-top: 32px; }
.breadcrumb { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 52px; font-size: 11px; color: #667365; }
.breadcrumb a { text-decoration: underline; text-underline-offset: 3px; }
.project-facts { display: grid; grid-template-columns: repeat(4, 1fr); padding: 28px 0; border-bottom: 1px solid #cbd2c5; }
.project-facts dt { margin-bottom: 6px; font-size: 10px; color: #667365; text-transform: uppercase; letter-spacing: 1px; }
.project-facts dd { margin: 0; font-size: 16px; }
.project-nav { position: sticky; top: 0; z-index: 20; border-bottom: 1px solid #cbd2c5; background: #f7f6f2; }
.project-nav .container { display: flex; gap: 36px; padding-top: 20px; padding-bottom: 20px; overflow-x: auto; }
.project-nav a { flex: 0 0 auto; font-size: 12px; }
.editorial-layout { display: grid; grid-template-columns: 1fr 1.2fr; gap: 100px; }
.editorial-copy > p:not(.large-copy) { color: #526353; }
.small-quote { margin-top: 32px; padding: 24px 0 24px 24px; border-left: 2px solid #9c5639; }
.small-quote p { font-family: Georgia, serif; font-size: 24px; line-height: 1.4; }
.small-quote footer { margin-top: 16px; font-size: 11px; color: #667365; }
.gallery-section { padding: 88px 0; background: #e8ebdf; }
.gallery-links { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 20px; }
.gallery-links a { padding: 8px 16px; border: 1px solid #b6c2ae; font-size: 12px; transition: background-color .2s ease; }
.gallery-links a:hover { background: #273b34; border-color: #273b34; color: #fff; }
.gallery-strip { display: flex; gap: 24px; overflow-x: auto; overflow-y: hidden; scroll-snap-type: x mandatory; scroll-behavior: smooth; scroll-padding: 0; padding-bottom: 16px; }
.gallery-slide { flex: 0 0 82%; min-width: 0; scroll-snap-align: start; }
.gallery-slide img { height: 420px; object-fit: cover; }
.gallery-slide figcaption { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding-top: 16px; font-size: 12px; }
.gallery-slide figcaption strong { font-weight: 400; }
.gallery-slide figcaption span, .image-note { color: #667365; }
.image-note { margin-top: 12px; font-size: 11px; }
.room-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.room-card { padding: 28px; border: 1px solid #cbd2c5; background: #fcfbf8; }
.room-tag { display: inline-block; margin-bottom: 28px; padding: 4px 10px; border-radius: 20px; background: #e8ebdf; font-size: 10px; }
.room-card h3 { margin-bottom: 18px; }
.room-card p, .room-card ul { font-size: 14px; color: #667365; }
.room-card ul { margin-top: 22px; padding-left: 18px; }
.room-card li { margin-top: 6px; }
.material-list { margin-top: 28px; }
.material-list > div { padding: 18px 0; border-top: 1px solid #cbd2c5; }
.material-list dt { display: flex; align-items: center; gap: 12px; font-size: 14px; }
.material-list dd { margin: 10px 0 0 34px; font-size: 13px; color: #667365; }
.swatch { display: block; width: 22px; height: 22px; flex: 0 0 22px; border-radius: 50%; }
.swatch-wood { background: #b99572; }
.swatch-stone { background: #bcb9aa; }
.swatch-plaster { background: #e1d8c4; border: 1px solid #cbbd9e; }
.journal-section { padding: 80px 0; background: #273b34; color: #f7f6f2; }
.journal-section h2 { margin-bottom: 36px; font-size: 44px; }
.journal-columns { columns: 2 280px; column-gap: 56px; font-size: 15px; color: #d4dbce; }
.journal-columns p { margin-bottom: 18px; }
.journal-columns p + p { margin-top: 0; }
.planning-layout { display: grid; grid-template-columns: 1.8fr 1fr; gap: 48px; align-items: start; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13px; text-align: left; }
caption { padding: 0 0 20px; text-align: left; font-size: 14px; }
th, td { padding: 16px 12px; border-bottom: 1px solid #cbd2c5; }
thead { background: #e8ebdf; }
thead th { font-size: 11px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }
tbody th { font-weight: 400; }
tbody tr:hover { background: #eceee6; }
tfoot { background: #e8ebdf; }
.number-cell { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
.planning-note { padding: 28px; border-top: 2px solid #9c5639; background: #eee9df; }
.planning-note h3 { margin-bottom: 20px; }
.planning-note p:not(.eyebrow) { font-size: 13px; color: #667365; }
.process-section { padding-top: 16px; padding-bottom: 32px; }
.process-section h2 { margin-bottom: 40px; }
.project-timeline { padding: 0; list-style: none; }
.project-timeline li { display: grid; grid-template-columns: 70px 1fr 140px; gap: 28px; padding: 28px 0; border-top: 1px solid #cbd2c5; }
.project-timeline li:last-child { border-bottom: 1px solid #cbd2c5; }
.project-timeline .step-number { margin: 0; }
.project-timeline p { max-width: 650px; margin-top: 10px; font-size: 14px; color: #667365; }
.timeline-phase { padding-top: 6px; font-size: 11px; text-align: right; color: #667365; }
.inquiry-section { padding: 96px 0; background: #e8ebdf; }
.inquiry-layout { display: grid; grid-template-columns: 1fr 1.2fr; gap: 96px; }
.inquiry-layout h2 { margin-bottom: 28px; }
.inquiry-layout > div > p:not(.eyebrow) { max-width: 340px; color: #526353; }
.inquiry-note { max-width: 340px; margin-top: 36px; padding: 24px; border: 1px solid #b8c4b0; }
.inquiry-note h3 { font-size: 16px; margin-bottom: 12px; }
.inquiry-note p { font-size: 12px; color: #526353; }
.inquiry-form fieldset { margin: 0; padding: 0; min-width: 0; border: 0; }
.inquiry-form > fieldset > legend { margin-bottom: 28px; font-family: Georgia, serif; font-size: 23px; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.form-field { margin-bottom: 22px; min-width: 0; }
.form-field > label { display: block; margin-bottom: 8px; font-size: 12px; }
.required { color: #9c5639; }
.form-field input, .form-field select, .form-field textarea { display: block; width: 100%; min-width: 0; padding: 13px 14px; border: 1px solid #b8c4b0; border-radius: 0; background: #f7f6f2; color: #273b34; font-size: 14px; line-height: 1.5; }
.form-field textarea { resize: vertical; min-height: 140px; }
.field-help { margin-top: 8px; font-size: 11px; color: #667365; }
.inquiry-form .radio-group { margin: 4px 0 24px; }
.radio-group legend { margin-bottom: 12px; font-size: 12px; }
.radio-group label, .checkbox-label { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; font-size: 12px; cursor: pointer; }
input[type="checkbox"], input[type="radio"] { flex: 0 0 18px; width: 18px; height: 18px; margin: 0; accent-color: #496453; }
.form-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 24px; margin: 28px 0 16px; }
.reset-button { padding: 8px 0; border: 0; border-bottom: 1px solid #8a9689; background: transparent; color: #273b34; font-size: 12px; }
.reset-button:hover { color: #a24d2c; }
.next-project { display: flex; justify-content: space-between; align-items: center; gap: 40px; padding-top: 80px; padding-bottom: 80px; border-bottom: 1px solid #d7dcd2; }
.next-project h2 { font-size: 44px; }
@media (max-width: 1000px) {
  .container { padding-left: 32px; padding-right: 32px; }
  h1 { font-size: 72px; }
  h2 { font-size: 44px; }
  .header-contact { display: none; }
  .hero-heading, .section-heading { gap: 40px; }
  .studio-layout, .material-section, .faq-layout, .editorial-layout, .inquiry-layout { gap: 48px; }
  .project-grid, .process-grid { gap: 20px; }
  .project-image img { height: 210px; }
  .room-grid { grid-template-columns: 1fr; }
  .room-card { display: block; }
  .planning-layout { grid-template-columns: 1fr; }
  .gallery-slide img { height: 340px; }
  .studio-facts { gap: 24px; }
  .form-row { grid-template-columns: 1fr; gap: 0; }
}
@media (max-width: 680px) {
  .container { padding-left: 22px; padding-right: 22px; }
  .header-inner { min-height: 96px; gap: 20px; }
  .wordmark { font-size: 27px; }
  .main-nav { justify-content: flex-end; flex-wrap: wrap; gap: 6px 18px; max-width: 230px; font-size: 11px; }
  .main-nav a { padding: 2px 0; }
  h1 { font-size: 58px; letter-spacing: -2px; }
  h2 { font-size: 38px; letter-spacing: -1px; }
  h3 { font-size: 20px; }
  .hero { padding-top: 44px; }
  .hero-heading, .section-heading, .studio-layout, .material-section, .faq-layout, .editorial-layout, .inquiry-layout { grid-template-columns: 1fr; gap: 28px; }
  .hero-heading { margin-bottom: 30px; }
  .hero-intro { max-width: 100%; font-size: 15px; }
  .hero-intro p { margin-bottom: 18px; }
  .eyebrow { margin-bottom: 18px; font-size: 10px; letter-spacing: 1.5px; }
  .hero-figure figcaption { position: static; padding: 12px 14px; font-size: 10px; }
  .hero-footnote { font-size: 9px; }
  .section { padding-top: 64px; padding-bottom: 64px; }
  .section-heading { margin-bottom: 32px; }
  .section-heading > p { max-width: 100%; font-size: 14px; }
  .project-grid, .process-grid { grid-template-columns: 1fr; gap: 36px; }
  .project-image img { height: auto; }
  .project-card { padding-bottom: 24px; }
  .studio-section { padding: 64px 0; }
  .studio-copy { padding-top: 0; }
  .large-copy { font-size: 24px; }
  .studio-facts { justify-content: space-between; gap: 18px; }
  .step-number { margin-bottom: 20px; }
  .material-section { padding-top: 8px; padding-bottom: 64px; }
  .material-copy h2 { margin-bottom: 24px; }
  .quote-section { padding-top: 52px; padding-bottom: 52px; }
  .quote-section p { font-size: 41px; }
  .faq-layout > div > p:not(.eyebrow) { max-width: 100%; }
  .faq-list summary { padding: 20px 0; font-size: 14px; }
  .contact-band { padding: 60px 0; }
  .contact-layout { flex-direction: column; align-items: flex-start; gap: 28px; }
  .contact-layout h2 { font-size: 56px; }
  .site-footer { padding-top: 44px; }
  .footer-top { grid-template-columns: 1fr; gap: 28px; padding-bottom: 32px; }
  .footer-top nav { flex-direction: row; flex-wrap: wrap; gap: 20px; }
  .footer-bottom { flex-direction: column; gap: 8px; }
  .breadcrumb { margin-bottom: 36px; font-size: 10px; gap: 9px; }
  .project-facts { grid-template-columns: 1fr 1fr; gap: 24px; }
  .project-facts dd { font-size: 14px; }
  .project-nav .container { gap: 24px; padding-top: 16px; padding-bottom: 16px; }
  .project-nav a { font-size: 11px; }
  .gallery-section { padding: 60px 0; }
  .gallery-slide { flex-basis: 90%; }
  .gallery-slide img { height: 260px; }
  .gallery-slide figcaption { display: block; font-size: 11px; }
  .gallery-slide figcaption span { display: block; margin-top: 4px; }
  .gallery-links { gap: 8px; }
  .gallery-links a { padding: 7px 10px; font-size: 10px; }
  .room-card { padding: 24px; }
  .journal-section { padding: 56px 0; }
  .journal-section h2 { font-size: 34px; }
  .journal-columns { columns: 1; }
  .planning-layout { gap: 28px; }
  th, td { padding: 12px 8px; font-size: 12px; }
  .project-timeline li { grid-template-columns: 38px 1fr; gap: 16px; }
  .project-timeline .step-number { font-size: 30px; }
  .timeline-phase { grid-column: 2; padding: 0; text-align: left; }
  .process-section { padding-top: 0; }
  .inquiry-section { padding: 64px 0; }
  .inquiry-note { max-width: 100%; margin-top: 24px; }
  .inquiry-layout > div > p:not(.eyebrow) { max-width: 100%; }
  .inquiry-form { margin-top: 12px; }
  .next-project { flex-direction: column; align-items: flex-start; padding-top: 60px; padding-bottom: 60px; gap: 28px; }
  .next-project h2 { font-size: 34px; }
}
@media (max-width: 380px) {
  .container { padding-left: 16px; padding-right: 16px; }
  h1 { font-size: 48px; }
  .main-nav { max-width: 180px; gap: 5px 12px; font-size: 10px; }
  .quote-section p { font-size: 34px; }
}
@media (prefers-reduced-motion: reduce) {
  html, .gallery-strip { scroll-behavior: auto; }
  .project-image img, .button, .gallery-links a { transition: none; }
}

