* { box-sizing: border-box; }
body { margin: 0; background: #f7f6f2; color: #273b34; font: 400 16px/1.6 Arial, Helvetica, sans-serif; }
h1, h2, p { margin: 0; }
a { color: inherit; text-decoration: none; cursor: pointer; }
a:focus-visible { outline: 2px solid #c96a43; outline-offset: 5px; }
.container { width: 100%; max-width: 1100px; padding: 0 32px; margin: 0 auto; }
.page-header { border-bottom: 1px solid #cbd2c5; }
.header-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 88px; font-size: 13px; }
.brand { font-weight: 700; letter-spacing: 2px; }
.intro { padding: 64px 0 40px; max-width: 800px; }
.eyebrow, .case-number { font-size: 11px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }
.eyebrow { margin-bottom: 20px; }
h1 { font: 400 58px/1.1 Georgia, serif; margin-bottom: 24px; }
.lead { font-size: 20px; }
.instructions { padding-left: 24px; margin: 24px 0; }
.instructions li { margin-bottom: 8px; }
.note { color: #566657; font-size: 14px; }
.test-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.test-card { min-width: 0; padding: 24px; background: #fff; border: 1px solid #cbd2c5; }
.case-number { color: #8a4a32; margin-bottom: 10px; }
.test-card h2 { font-size: 22px; line-height: 1.3; margin-bottom: 12px; }
.test-card > p:not(.case-number) { font-size: 14px; }
.stage { display: flex; align-items: center; justify-content: center; gap: 12px; height: 144px; margin: 24px 0 18px; padding: 16px; background: #273b34; }
.motion { display: inline-flex; align-items: center; justify-content: space-between; gap: 32px; width: 270px; max-width: 100%; padding: 16px 24px; border: 1px solid #f7f6f2; border-radius: 0; background: #f7f6f2; color: #273b34; font-size: 13px; line-height: 1.5; transform-origin: center center; }
.original { transition: background-color .2s ease, transform .2s ease, box-shadow .2s ease; }
.original:hover { background: #e8ebdf; border-color: #e8ebdf; color: #273b34; transform: translateY(-2px); box-shadow: 0 6px 16px rgb(39 59 52 / 12%); }
.move-small { transition: transform .2s ease; }
.move-small:hover { transform: translateY(-2px); }
.move-slow { transition: transform .8s linear; }
.move-slow:hover { transform: translateY(-12px); }
.color-only { transition: background-color .6s ease; }
.color-only:hover { background: #9fb28d; }
.shadow-only { transition: box-shadow .6s ease; }
.shadow-only:hover { box-shadow: 0 10px 20px rgb(0 0 0 / 40%); }
.combined-slow { transition: background-color 1s ease, transform 1s ease, box-shadow 1s ease; }
.combined-slow:hover { background: #9fb28d; transform: translateY(-8px); box-shadow: 0 10px 20px rgb(0 0 0 / 40%); }
.stable-child { transition: transform .8s linear; }
.stable-pad:hover .stable-child { transform: translateY(-12px); }
.scale-only { transition: transform .6s ease; }
.scale-only:hover { transform: scale(1.04); }
.rotate-only { transition: transform .6s ease; }
.rotate-only:hover { transform: rotate(2deg); }
.opacity-only { transition: opacity .6s ease; }
.opacity-only:hover { opacity: .55; }
.twin-stage .motion { width: 140px; justify-content: center; padding: 16px 12px; }
.reverse-test { transition: transform .8s ease; }
.reverse-test:hover { transform: translateY(-8px); }
.instant { transition: none; }
.clipped-stage { height: 72px; padding: 0 16px; overflow: hidden; }
.expectation { color: #566657; border-top: 1px solid #e4e8df; padding-top: 14px; }
.results { padding: 64px 0; max-width: 800px; }
.results h2 { font: 400 36px/1.2 Georgia, serif; margin-bottom: 20px; }
.results ul { padding-left: 24px; margin: 24px 0; }
.back-link { display: inline-block; margin-top: 24px; padding-bottom: 4px; border-bottom: 1px solid #273b34; }
.page-footer { padding: 28px 0; border-top: 1px solid #cbd2c5; font-size: 12px; color: #566657; }
@media (max-width: 740px) {
  .test-grid { grid-template-columns: 1fr; }
  .container { padding-left: 20px; padding-right: 20px; }
  .test-card { padding: 20px; }
  h1 { font-size: 42px; }
  .intro { padding-top: 40px; }
}
@media (max-width: 380px) {
  .container { padding-left: 12px; padding-right: 12px; }
  .test-card { padding: 14px; }
  .motion { padding-left: 14px; padding-right: 14px; gap: 16px; }
  .header-row { flex-wrap: wrap; padding-top: 18px; padding-bottom: 18px; }
}

