(() => {
  'use strict';

  const byId = id => document.getElementById(id);
  const money = new Intl.NumberFormat('de-DE', {
    style: 'currency', currency: 'EUR', maximumFractionDigits: 0
  });
  const savedKey = 'fernweh:saved:v1';
  const noteKey = 'fernweh:note:v1';
  const definitions = [
    ['uferhaus', 'Uferhaus', 'see', 168, 4],
    ['waldlicht', 'Waldlicht', 'wald', 142, 2],
    ['gipfelruhe', 'Gipfelruhe', 'berge', 184, 4],
    ['seeatelier', 'Seeatelier', 'see', 156, 2],
    ['mooshuette', 'Mooshütte', 'wald', 128, 2],
    ['bergfenster', 'Bergfenster', 'berge', 176, 6]
  ];
  const regions = { see: 'Am See', wald: 'Im Wald', berge: 'In den Bergen' };
  const stays = new Map(definitions.map(([id, name, region, price, guests]) => {
    const card = byId('stay-' + id);
    return [id, { id, name, region, price, guests, card }];
  }));
  const savedRows = new Map();
  const search = byId('search');
  const region = byId('region');
  const onlySaved = byId('only-saved');
  const dialog = byId('detail-dialog');
  const bookingForm = byId('booking-form');
  const bookingStay = byId('booking-stay');
  const arrival = byId('arrival');
  const nights = byId('nights');
  const guests = byId('guests');
  const fullName = byId('full-name');
  const email = byId('email');
  const message = byId('message');
  const newsletter = byId('newsletter');
  const submit = byId('booking-submit');
  const submitCaption = submit.textContent;
  const progress = byId('booking-progress');
  const progressFill = byId('booking-progress-fill');
  let detailId = null;
  let toastTimer = null;
  let pending = null;
  let confirmed = false;

  function text(element, value) {
    const next = String(value);
    if (element.textContent !== next) element.textContent = next;
  }

  function toast(messageText) {
    clearTimeout(toastTimer);
    const element = byId('toast');
    text(element, messageText);
    element.hidden = false;
    toastTimer = setTimeout(() => { element.hidden = true; }, 2600);
  }

  // Filters and saved houses use the same six fixed house identities.
  function validSaved(raw) {
    try {
      const values = JSON.parse(raw || '[]');
      return new Set(Array.isArray(values) ? values.filter(id => stays.has(id)) : []);
    } catch (_) {
      return new Set();
    }
  }

  let saved;
  try { saved = validSaved(localStorage.getItem(savedKey)); }
  catch (_) { saved = new Set(); }

  function filterStays() {
    const query = search.value.trim().toLowerCase();
    let count = 0;
    for (const stay of stays.values()) {
      const haystack = (stay.name + ' ' + regions[stay.region] + ' ' +
        (stay.card.getAttribute('data-location') || '')).toLowerCase();
      const visible = haystack.includes(query) &&
        (region.value === 'alle' || stay.region === region.value) &&
        (!onlySaved.checked || saved.has(stay.id));
      if (stay.card.hidden === visible) stay.card.hidden = !visible;
      if (visible) count++;
    }
    text(byId('result-count'), count);
    byId('empty-results').hidden = count !== 0;
  }

  function savedRow(stay) {
    const row = document.createElement('tr');
    const house = document.createElement('td');
    const open = document.createElement('button');
    open.type = 'button';
    open.setAttribute('data-details', stay.id);
    text(open, stay.name);
    house.append(open);
    row.append(house);
    for (const value of [regions[stay.region], money.format(stay.price)]) {
      const cell = document.createElement('td');
      text(cell, value);
      row.append(cell);
    }
    const action = document.createElement('td');
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.setAttribute('data-remove', stay.id);
    remove.setAttribute('aria-label', stay.name + ' aus der Merkliste entfernen');
    text(remove, 'Entfernen');
    action.append(remove);
    row.append(action);
    return row;
  }

  function renderSaved() {
    for (const button of document.querySelectorAll('button[data-save]')) {
      const active = saved.has(button.getAttribute('data-save'));
      const pressed = String(active);
      if (button.getAttribute('aria-pressed') !== pressed) button.setAttribute('aria-pressed', pressed);
      text(button, active ? 'Gemerkt' : 'Merken');
    }
    // Retain unchanged table rows, including their native controls.
    const body = byId('saved-body');
    for (const [id, row] of savedRows) {
      if (!saved.has(id)) { row.remove(); savedRows.delete(id); }
    }
    let index = 0;
    for (const id of saved) {
      let row = savedRows.get(id);
      if (!row) { row = savedRow(stays.get(id)); savedRows.set(id, row); }
      const current = body.children[index] || null;
      if (current !== row) body.insertBefore(row, current);
      index++;
    }
    text(byId('saved-count'), saved.size);
    byId('saved-empty').hidden = saved.size !== 0;
    byId('clear-saved').disabled = saved.size === 0;
    updateDetailSave();
    filterStays();
  }

  function saveChanged() {
    try { localStorage.setItem(savedKey, JSON.stringify(Array.from(saved))); }
    catch (_) { /* The current page's list still works without persistent storage. */ }
    renderSaved();
  }

  function toggleSaved(id) {
    const stay = stays.get(id);
    if (!stay) return;
    const removed = saved.delete(id);
    if (!removed) saved.add(id);
    saveChanged();
    toast(stay.name + (removed ? ' wurde aus der Merkliste entfernt.' : ' ist jetzt gemerkt.'));
  }

  // One native dialog presents every house and keeps save state in sync.
  function updateDetailSave() {
    const active = detailId !== null && saved.has(detailId);
    const button = byId('detail-save');
    button.setAttribute('aria-pressed', String(active));
    text(button, active ? 'Gemerkt' : 'Merken');
  }

  function openDetails(id) {
    const stay = stays.get(id);
    if (!stay) return;
    detailId = id;
    text(byId('detail-title'), stay.name);
    text(byId('detail-location'), stay.card.getAttribute('data-location') || regions[stay.region]);
    text(byId('detail-copy'), stay.card.getAttribute('data-copy') || '');
    text(byId('detail-price'), money.format(stay.price));
    text(byId('detail-guests'), 'Bis zu ' + stay.guests + ' Gäste');
    for (const image of byId('detail-images').querySelectorAll('[data-detail-region]')) {
      const hidden = image.getAttribute('data-detail-region') !== stay.region;
      if (image.hidden !== hidden) image.hidden = hidden;
    }
    updateDetailSave();
    if (!dialog.open) dialog.showModal();
  }

  function closeDetails() {
    if (dialog.open) dialog.close();
    detailId = null;
  }
  dialog.addEventListener('close', () => { if (!dialog.open) detailId = null; });
  // Escape retains the native cancel behavior; the close event clears state.

  function readBooking() {
    return {
      stay: bookingStay.value, arrival: arrival.value,
      nights: Number(nights.value), guests: Number(guests.value),
      name: fullName.value.trim(), email: email.value.trim(),
      message: message.value, newsletter: newsletter.checked
    };
  }

  function updateBooking() {
    const stay = stays.get(bookingStay.value);
    const count = Number(nights.value);
    const guestCount = Number(guests.value);
    const validNights = Number.isInteger(count) && count >= 2 && count <= 14;
    guests.setCustomValidity(stay && guestCount > stay.guests
      ? stay.name + ' bietet Platz für höchstens ' + stay.guests + ' Gäste.' : '');
    fullName.setCustomValidity(fullName.value && !fullName.value.trim()
      ? 'Bitte geben Sie Ihren Namen ein.' : '');
    text(byId('booking-summary'), stay && validNights ? money.format(stay.price * count) : '—');
    text(byId('booking-note'), stay
      ? (validNights ? count + ' Nächte' : 'Bitte 2 bis 14 Nächte wählen') + ' · ' +
        guestCount + (guestCount === 1 ? ' Gast' : ' Gäste') + ' · ' + stay.name +
        ' · Platz für bis zu ' + stay.guests + ' Gäste'
      : 'Bitte wählen Sie ein Haus.');
    text(byId('guest-count'), guestCount);
    byId('guest-minus').disabled = guestCount <= 1;
    byId('guest-plus').disabled = guestCount >= 6;
  }

  function setBusy(busy) {
    submit.disabled = busy;
    text(submit, busy ? 'Wird vorbereitet…' : submitCaption);
    if (progress) progress.hidden = !busy;
  }

  function stopProgress(request, value) {
    if (request.frame !== null) cancelAnimationFrame(request.frame);
    request.frame = null;
    if (progressFill) progressFill.style.transform = 'scaleX(' + value + ')';
  }

  function startProgress(request) {
    if (!progressFill) return;
    const start = performance.now();
    progressFill.style.transform = 'scaleX(0)';
    function draw(timestamp) {
      request.frame = null;
      if (pending !== request) return;
      const value = Math.min(1, Math.max(0, (timestamp - start) / 650));
      progressFill.style.transform = 'scaleX(' + value + ')';
      if (value < 1) request.frame = requestAnimationFrame(draw);
    }
    request.frame = requestAnimationFrame(draw);
  }

  function cancelBooking(status) {
    if (!pending) return;
    const request = pending;
    pending = null;
    clearTimeout(request.timer);
    stopProgress(request, 0);
    request.resolve(false);
    setBusy(false);
    if (status) text(byId('booking-status'), status);
  }

  function bookingEdited() {
    cancelBooking('Die Angaben wurden geändert. Bitte bereiten Sie die Anfrage erneut vor.');
    if (confirmed) {
      confirmed = false;
      text(byId('booking-status'), 'Angaben geändert. Bereiten Sie Ihre aktualisierte Anfrage vor.');
    }
    updateBooking();
  }

  // This delay prepares a local summary. It does not contact a booking service.
  bookingForm.addEventListener('submit', async event => {
    event.preventDefault();
    if (pending) return;
    updateBooking();
    if (!bookingForm.reportValidity()) {
      text(byId('booking-status'), 'Bitte prüfen Sie die markierten Angaben und die Gästezahl.');
      return;
    }
    const snapshot = readBooking();
    const request = { snapshot, timer: null, frame: null, resolve: null };
    pending = request;
    confirmed = false;
    setBusy(true);
    text(byId('booking-status'), 'Ihre Angaben werden lokal zusammengestellt…');
    const finished = await new Promise(resolve => {
      request.resolve = resolve;
      request.timer = setTimeout(() => { request.timer = null; resolve(true); }, 650);
      startProgress(request);
    });
    if (!finished || pending !== request) return;
    // Catch programmatic edits too, even when no input event was dispatched.
    if (JSON.stringify(readBooking()) !== JSON.stringify(snapshot)) {
      cancelBooking('Die Angaben wurden geändert. Bitte bereiten Sie die Anfrage erneut vor.');
      updateBooking();
      return;
    }
    pending = null;
    stopProgress(request, 1);
    setBusy(false);
    confirmed = true;
    const stay = stays.get(snapshot.stay);
    text(byId('booking-status'), snapshot.name + ': ' + stay.name + ', ' + snapshot.nights +
      ' Nächte ab ' + snapshot.arrival + ', ' + snapshot.guests +
      (snapshot.guests === 1 ? ' Gast' : ' Gäste') + ', ' + money.format(stay.price * snapshot.nights) +
      '. ' + (snapshot.newsletter ? 'Newsletter gewünscht. ' : 'Kein Newsletter gewünscht. ') +
      'Die Anfrage wurde lokal vorbereitet; es wurde nichts versendet.');
    toast('Ihre Anfrage ist lokal vorbereitet. Es wurde nichts versendet.');
  });
  bookingForm.addEventListener('input', bookingEdited);
  bookingForm.addEventListener('change', bookingEdited);

  // Delegation also covers the removal buttons created in the saved table.
  document.addEventListener('click', event => {
    const button = event.target.closest('button');
    if (!button || button.disabled) return;
    if (button.hasAttribute('data-save')) { toggleSaved(button.getAttribute('data-save')); return; }
    if (button.hasAttribute('data-details')) { openDetails(button.getAttribute('data-details')); return; }
    if (button.hasAttribute('data-remove')) {
      const id = button.getAttribute('data-remove');
      if (saved.has(id)) toggleSaved(id);
      return;
    }
    switch (button.id) {
      case 'reset-filters':
        search.value = ''; region.value = 'alle'; onlySaved.checked = false;
        filterStays(); break;
      case 'clear-saved':
        saved.clear(); saveChanged(); toast('Ihre Merkliste ist jetzt leer.'); break;
      case 'detail-close': closeDetails(); break;
      case 'detail-save': toggleSaved(detailId); break;
      case 'detail-plan':
        if (detailId) { bookingStay.value = detailId; bookingEdited(); }
        closeDetails();
        bookingForm.scrollIntoView({ behavior: 'auto', block: 'start' });
        arrival.focus(); break;
      case 'guest-minus':
      case 'guest-plus':
        guests.value = String(Math.max(1, Math.min(6, Number(guests.value) +
          (button.id === 'guest-plus' ? 1 : -1))));
        bookingEdited(); break;
      case 'note-save':
        try {
          localStorage.setItem(noteKey, byId('trip-note').textContent);
          text(byId('note-status'), 'Ihre Notiz wurde auf diesem Gerät gespeichert.');
          toast('Notiz gespeichert.');
        } catch (_) {
          text(byId('note-status'), 'Die Notiz konnte hier nicht gespeichert werden. Ihr Text bleibt auf dieser Seite erhalten.');
        }
        break;
    }
  });
  search.addEventListener('input', filterStays);
  region.addEventListener('change', filterStays);
  onlySaved.addEventListener('change', filterStays);
  window.addEventListener('storage', event => {
    if (event.key === savedKey || event.key === null) {
      try { if (event.storageArea && event.storageArea !== localStorage) return; }
      catch (_) { return; }
      saved = validSaved(event.newValue);
      renderSaved();
    }
  });
  window.addEventListener('pagehide', () => {
    cancelBooking('');
    clearTimeout(toastTimer);
  });

  byId('newsletter-form').addEventListener('submit', event => {
    event.preventDefault();
    if (!event.currentTarget.reportValidity()) return;
    text(byId('newsletter-result'), 'Die Newsletter-Anmeldung für ' +
      byId('newsletter-email').value.trim() + ' wurde lokal vorbereitet; es wurde nichts versendet.');
  });

  // Plain text notes are persisted only by the explicit save button.
  try {
    const note = localStorage.getItem(noteKey);
    if (note !== null) {
      text(byId('trip-note'), note);
      text(byId('note-status'), 'Gespeicherte Notiz geladen. Änderungen speichern Sie mit „Notiz speichern“.');
    }
  } catch (_) {
    text(byId('note-status'), 'Der Notizspeicher ist hier nicht verfügbar. Sie können Ihre Notiz auf dieser Seite bearbeiten.');
  }
  byId('trip-note').addEventListener('input', () => {
    text(byId('note-status'), 'Notiz geändert. Die Änderungen sind noch nicht gespeichert.');
  });

  // A small native custom element keeps its own typographic style in Shadow DOM.
  if (!customElements.get('fernweh-note')) {
    class FernwehNote extends HTMLElement {
      constructor() {
        super();
        const root = this.attachShadow({ mode: 'open' });
        const style = document.createElement('style');
        style.textContent = ':host{display:block}p{margin:0;font:14px/1.6 Arial,sans-serif;color:#56675e;border-left:2px solid #c5714d;padding-left:16px}';
        const paragraph = document.createElement('p');
        paragraph.textContent = 'Gute Orte brauchen keine lange Packliste. Nur ein bisschen Zeit.';
        root.append(style, paragraph);
      }
    }
    customElements.define('fernweh-note', FernwehNote);
  }

  renderSaved();
  updateBooking();
})();

