/* One stylesheet for the browser and the Roblox website module. */
:root { --ink: #243f35; --muted: #627167; --paper: #f6f3eb; --line: #d4dbce; --accent: #a85839; --sage: #e5e9dd; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 24px; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 400 16px/1.65 Arial, Helvetica, sans-serif; }
h1, h2, h3, p, figure, blockquote, ol, ul { margin: 0; }
h1, h2 { font-family: Georgia, serif; font-weight: 400; line-height: 1.08; letter-spacing: -2px; }
h1 { font-size: 76px; }
h2 { font-size: 54px; }
h3 { font-size: 22px; font-weight: 400; line-height: 1.3; }
em { font-weight: 400; }
p + p { margin-top: 16px; }
a { color: inherit; text-decoration: none; cursor: pointer; }
a:hover { color: var(--accent); }
button, input, select, textarea { font: inherit; color: inherit; }
button, summary, select { cursor: pointer; }
button { border-radius: 0; }
img { display: block; width: 100%; height: auto; }
[hidden] { display: none !important; }
input, select, textarea { width: 100%; min-width: 0; padding: 13px 14px; border: 1px solid #aab8a7; border-radius: 2px; background: #fff; font-size: 14px; line-height: 1.5; }
input::placeholder, textarea::placeholder { color: #748076; }
textarea { min-height: 102px; resize: vertical; }
input[type="checkbox"] { width: 18px; height: 18px; margin: 2px 0 0; padding: 0; flex-shrink: 0; accent-color: #c5714d; }
label { display: block; margin-bottom: 8px; font-size: 13px; line-height: 1.5; }
a:focus-visible, button:focus-visible, summary:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
input:focus-visible, select:focus-visible, textarea:focus-visible { outline: auto; outline-offset: 0; }
button:disabled { opacity: .55; cursor: default; }
section[id] { scroll-margin-top: 24px; }
.container { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 48px; }
.section { padding-top: 100px; padding-bottom: 100px; }
.eyebrow { margin-bottom: 20px; font-size: 10px; font-weight: 700; letter-spacing: 1.8px; line-height: 1.6; text-transform: uppercase; }
.small-copy { color: var(--muted); font-size: 12px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; }
.skip-link { position: fixed; top: -100px; left: 16px; z-index: 100; padding: 12px 20px; background: var(--ink); color: #fff; }
.skip-link:focus { top: 12px; }
.announcement { display: flex; justify-content: center; gap: 30px; padding: 10px 24px; background: var(--ink); color: var(--paper); font-size: 11px; line-height: 1.5; }
.announcement > span { color: #c3cdbb; }
.announcement a { color: var(--paper); }
.announcement a:hover { color: #e7c9b1; }
.announcement a span { display: inline-block; margin-left: 8px; }
.site-header { border-bottom: 1px solid var(--line); }
.header-inner { display: flex; align-items: center; justify-content: space-between; gap: 32px; min-height: 104px; }
.brand { display: block; width: 224px; font: italic 42px/1 Georgia, serif; letter-spacing: -1.5px; }
.brand span { display: block; margin-top: 10px; font: 400 8px/1.5 Arial, sans-serif; letter-spacing: 1.4px; }
.main-nav { display: flex; gap: 28px; font-size: 12px; }
.main-nav a { padding: 9px 0; border-bottom: 1px solid transparent; }
.main-nav a:hover { border-bottom-color: var(--accent); }
.saved-link { display: inline-flex; align-items: center; gap: 12px; font-size: 12px; }
.saved-link output { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; border: 1px solid #aab8a7; border-radius: 50%; font-size: 11px; }
.hero { padding-top: 64px; }
.hero-heading { display: grid; grid-template-columns: minmax(0, 1.85fr) minmax(0, 1fr); gap: 60px; align-items: end; margin-bottom: 42px; }
.hero-heading h1 em { color: var(--accent); }
.small-dot { display: inline-block; width: 6px; height: 6px; margin: 0 8px 2px 0; border-radius: 50%; background: var(--accent); }
.hero-intro { padding-bottom: 9px; max-width: 300px; font-size: 15px; }
.hero-intro p { margin-bottom: 25px; }
.text-link { display: inline-block; padding-bottom: 5px; border-bottom: 1px solid #8e9c8c; font-size: 12px; }
.text-link span { display: inline-block; margin-left: 18px; }
.hero-figure { position: relative; overflow: hidden; background: #b7c9cd; border-radius: 4px; }
.hero-figure > img { height: 440px; object-fit: cover; }
.hero-figure figcaption { position: absolute; left: 28px; bottom: 28px; display: flex; align-items: center; justify-content: space-between; gap: 24px; width: 330px; max-width: calc(100% - 56px); padding: 18px 20px; background: var(--paper); }
.image-kicker { display: block; margin-bottom: 5px; font-size: 9px; letter-spacing: 1px; text-transform: uppercase; }
.hero-figure figcaption strong { font-family: Georgia, serif; font-size: 19px; font-weight: 400; }
.round-link { display: inline-flex; justify-content: center; align-items: center; width: 35px; height: 35px; flex-shrink: 0; border: 1px solid #9aa88f; border-radius: 50%; }
.hero-bottom { display: flex; justify-content: space-between; gap: 20px; padding: 17px 0; font-size: 10px; color: var(--muted); border-bottom: 1px solid var(--line); }
.intro-strip { display: grid; grid-template-columns: 1.1fr repeat(3, minmax(0, 1fr)); gap: 34px; padding-top: 48px; padding-bottom: 48px; }
.intro-strip > p { padding-top: 8px; font: 400 28px/1.3 Georgia, serif; }
.intro-strip > p em { color: var(--accent); }
.promise-number { display: block; margin-bottom: 13px; color: var(--accent); font-size: 10px; }
.intro-strip h3 { margin-bottom: 9px; font-size: 15px; font-weight: 700; }
.intro-strip div p { font-size: 12px; color: var(--muted); }
.section-heading { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); align-items: end; gap: 70px; margin-bottom: 40px; }
.section-heading > p { max-width: 365px; font-size: 14px; color: var(--muted); }
.filter-bar { display: flex; align-items: end; gap: 20px; padding: 22px 24px; border: 1px solid var(--line); background: #eeefe5; }
.filter-search { flex: 1; min-width: 0; }
.filter-region { width: 220px; }
.check-label { display: flex; align-items: flex-start; gap: 10px; font-size: 12px; cursor: pointer; }
.filter-saved { width: 178px; margin: 0 0 14px; }
.results-line { display: flex; justify-content: space-between; gap: 12px; margin: 22px 0; font-size: 11px; color: var(--muted); }
.results-line output { display: inline-block; width: 13px; font-weight: 700; color: var(--ink); }
.plain-button { padding: 0 0 2px; border: 0; border-bottom: 1px solid #95a08e; background: transparent; font-size: 11px; line-height: 1.6; }
.plain-button:hover { color: var(--accent); border-bottom-color: var(--accent); }
.plain-button span { margin-left: 7px; }
.empty-state { padding: 36px; margin-bottom: 24px; border: 1px dashed #aab8a7; background: #eeefe5; text-align: center; }
.stay-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; align-items: start; }
.stay-card { min-width: 0; border: 1px solid var(--line); background: #fffef9; }
.stay-image { position: relative; background: var(--sage); }
.stay-image img { height: 224px; object-fit: cover; }
.image-label { position: absolute; top: 15px; left: 15px; padding: 5px 9px; background: var(--paper); font-size: 9px; }
.stay-content { padding: 22px; }
.stay-meta { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 5px; margin-bottom: 14px; color: var(--muted); font-size: 9px; }
.stay-card h3 { font: 400 31px/1.2 Georgia, serif; margin-bottom: 13px; letter-spacing: -.4px; }
.stay-content > p { min-height: 62px; font-size: 13px; color: var(--muted); }
.amenities { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 17px; min-height: 54px; align-content: start; }
.amenities span { padding: 3px 7px; background: #eef1e7; font-size: 9px; color: #52644e; }
.stay-price { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin: 18px 0; padding-top: 18px; border-top: 1px solid var(--line); }
.stay-price p { font-size: 11px; }
.stay-price strong { font-size: 22px; font-weight: 400; }
.stay-price p span { color: var(--muted); }
.save-button { width: 70px; padding: 7px 4px; border: 1px solid #bdc7b5; background: transparent; font-size: 11px; transition: background-color .2s ease, color .2s ease; }
.save-button:hover, .save-button[aria-pressed="true"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.button { display: inline-flex; justify-content: space-between; align-items: center; gap: 22px; padding: 14px 18px; border: 1px solid var(--ink); font-size: 12px; line-height: 1.5; transition: transform .2s ease, background-color .2s ease, color .2s ease, box-shadow .2s ease; }
.button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 5px 12px rgb(36 63 53 / 12%); }
.button-primary { background: var(--ink); color: var(--paper); }
.button-primary:hover:not(:disabled) { background: #3b5a44; }
.button-outline { background: transparent; color: var(--ink); }
.button-outline:hover { background: #e7ebdf; }
.card-detail { width: 100%; }
.section-footnote { margin-top: 26px; font-size: 10px; color: var(--muted); }
.story-band { padding: 82px 0; background: var(--sage); }
.story-layout { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); align-items: center; gap: 76px; }
.story-image img { height: 530px; object-fit: cover; }
.story-image figcaption { margin-top: 12px; font-size: 10px; color: var(--muted); }
.story-copy h2 { margin-bottom: 24px; }
.story-copy .large-copy { font: 400 22px/1.5 Georgia, serif; }
.story-copy > p:not(.eyebrow):not(.large-copy) { font-size: 13px; color: #52644e; }
.story-copy .text-link { margin-top: 26px; }
.plan-layout { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 28px; }
.saved-panel, .note-panel { min-width: 0; padding: 28px; border: 1px solid var(--line); background: #fffef9; }
.panel-heading { display: flex; justify-content: space-between; flex-wrap: wrap; align-items: center; gap: 12px; margin-bottom: 24px; }
.panel-heading h3 { font-size: 19px; }
.saved-empty { padding: 18px 0; font-size: 13px; color: var(--muted); }
.table-scroll { overflow-x: auto; scrollbar-width: thin; scrollbar-color: #8a9a79 #eef1e7; margin: 0 0 24px; }
.saved-table { width: 100%; min-width: 390px; border-collapse: collapse; font-size: 12px; }
.saved-table caption { caption-side: top; padding-bottom: 12px; font-size: 10px; text-align: left; color: var(--muted); }
.saved-table th { padding: 12px 8px; background: #eef1e7; text-align: left; color: #5f705e; font-size: 10px; font-weight: 400; }
.saved-table td { padding: 16px 8px; border-bottom: 1px solid var(--line); vertical-align: baseline; }
.saved-table th:first-child, .saved-table td:first-child { padding-left: 12px; }
.saved-table td:nth-child(3) { white-space: nowrap; }
.saved-table td:last-child { text-align: right; }
.saved-table button { padding: 3px 0; border: 0; border-bottom: 1px solid #95a08e; background: transparent; font-size: 10px; }
.saved-table button:hover { color: var(--accent); }
.note-panel { background: #eeefe5; }
.note-panel .eyebrow { color: var(--accent); margin-bottom: 10px; }
.note-panel > p:not(.eyebrow) { margin-top: 14px; font-size: 12px; color: var(--muted); }
.trip-note { min-height: 135px; margin-top: 20px; padding: 15px; border: 1px solid #aab8a7; background: #fffef9; font-size: 14px; white-space: pre-wrap; overflow-wrap: anywhere; }
.note-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 14px; }
.note-actions .button { padding: 9px 13px; font-size: 11px; }
fernweh-note { display: block; margin-top: 26px; }
.quote-band { padding: 72px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); text-align: center; }
.quote-band p { font: 400 48px/1.25 Georgia, serif; letter-spacing: -1px; }
.quote-band em { color: var(--accent); }
.quote-band span { display: block; margin-top: 24px; color: var(--muted); font-size: 10px; letter-spacing: 1px; text-transform: uppercase; }
.journal-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; }
.journal-card { position: relative; padding: 32px 26px; border-top: 2px solid #8c9b7c; background: #eeefe5; }
.journal-number { display: block; margin-bottom: 30px; color: #a2ad94; font: 400 42px/1 Georgia, serif; }
.journal-card .eyebrow { font-size: 8px; margin-bottom: 18px; }
.journal-card h3 { margin-bottom: 24px; font: 400 30px/1.18 Georgia, serif; }
.journal-card > p:not(.eyebrow) { font-size: 12px; color: #5a6b55; }
.booking-band { padding: 88px 0; background: var(--ink); color: var(--paper); }
.booking-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); align-items: start; gap: 80px; }
.booking-intro { padding-top: 20px; }
.booking-intro .eyebrow { color: #b9cbb0; }
.booking-intro h2 { margin-bottom: 30px; font-size: 64px; }
.booking-intro h2 em { color: #e1c4a5; }
.booking-intro > p:not(.eyebrow) { max-width: 330px; font-size: 14px; color: #c1cdbb; }
.booking-steps { padding-left: 22px; margin-top: 30px; font-size: 13px; }
.booking-steps li { padding-left: 5px; margin-bottom: 10px; }
.booking-promise { margin-top: 48px; padding-top: 20px; border-top: 1px solid #59725a; max-width: 325px; }
.booking-promise strong { font-size: 13px; font-weight: 400; }
.booking-promise p { margin-top: 9px; font-size: 11px; color: #b9cbb0; }
.booking-form { min-width: 0; padding: 30px; background: var(--paper); color: var(--ink); }
.form-heading { display: flex; justify-content: space-between; flex-wrap: wrap; align-items: center; gap: 10px; padding-bottom: 20px; margin-bottom: 24px; border-bottom: 1px solid var(--line); }
.form-heading h3 { font-size: 19px; }
.form-heading > span { font-size: 10px; color: var(--muted); }
.form-field { min-width: 0; margin-bottom: 18px; }
.form-row { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.required-mark { color: var(--accent); }
.optional-mark { display: inline-block; margin-left: 6px; font-size: 10px; color: var(--muted); }
.guest-row { display: flex; align-items: end; gap: 18px; margin-bottom: 24px; }
.guest-row > div:first-child { flex: 1; min-width: 0; }
.guest-stepper { display: flex; align-items: center; border: 1px solid #aab8a7; background: #fff; height: 48px; }
.guest-stepper button { width: 40px; height: 46px; padding: 0; border: 0; background: transparent; font-size: 20px; }
.guest-stepper button:hover { background: var(--sage); }
.guest-stepper output { display: inline-flex; justify-content: center; align-items: center; width: 30px; height: 46px; font-size: 14px; }
.price-summary { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 18px 0; margin-bottom: 25px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.price-summary > div > span { font-size: 12px; }
.price-summary p { margin-top: 5px; font-size: 10px; color: var(--muted); }
.price-summary output { min-width: 96px; text-align: right; white-space: nowrap; font: 400 30px/1.3 Georgia, serif; }
.newsletter-check { margin-bottom: 22px; }
.submit-button { width: 100%; justify-content: center; }
.booking-progress { overflow: hidden; height: 3px; margin-top: 8px; background: #d4dbce; }
#booking-progress-fill { width: 100%; height: 3px; background: #a85839; transform: scaleX(0); transform-origin: left center; }
.booking-status { min-height: 46px; margin-top: 12px; font-size: 11px; color: var(--muted); }
.booking-status.is-success { color: #264d39; }
.booking-status.is-error { color: #973e2c; }
.faq-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: 80px; }
.faq-intro { max-width: 280px; margin: 22px 0; font-size: 13px; color: var(--muted); }
.faq-list details { border-bottom: 1px solid var(--line); }
.faq-list details:first-child { border-top: 1px solid var(--line); }
.faq-list summary { padding: 24px 8px; font-size: 14px; }
.faq-list summary:hover { color: var(--accent); }
.faq-body { padding: 0 24px 24px; font-size: 13px; color: var(--muted); }
.newsletter-band { padding: 60px 0; background: #e5e9dd; }
.newsletter-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); gap: 80px; align-items: center; }
.newsletter-layout h2 { font-size: 44px; }
.newsletter-layout .eyebrow { margin-bottom: 15px; }
.newsletter-layout > div > p:not(.eyebrow) { font-size: 12px; margin-top: 20px; color: var(--muted); }
.newsletter-fields { display: flex; gap: 10px; }
.newsletter-fields input { flex: 1; min-width: 0; }
.newsletter-fields button { flex-shrink: 0; }
.newsletter-result { margin-top: 12px; font-size: 11px; color: var(--muted); }
.site-footer { padding: 62px 0 22px; }
.footer-top { display: grid; grid-template-columns: 1.3fr 1fr 1fr 1.2fr; gap: 35px; padding-bottom: 50px; }
.footer-top .brand { font-size: 38px; width: auto; }
.footer-top .brand span { font-size: 7px; }
.footer-top > div > p:not(.eyebrow) { margin-top: 22px; color: var(--muted); font-size: 12px; }
.footer-top nav { display: flex; flex-direction: column; align-items: start; gap: 9px; font-size: 12px; }
.footer-top .eyebrow { margin: 0 0 13px; }
.footer-note .text-link { margin-top: 22px; font-size: 11px; }
.footer-bottom { display: flex; justify-content: space-between; gap: 20px; padding-top: 19px; border-top: 1px solid var(--line); font-size: 9px; color: var(--muted); }
.detail-dialog { width: 620px; max-width: calc(100% - 32px); max-height: 90vh; margin: auto; padding: 24px; overflow-y: auto; border: 1px solid var(--line); background: var(--paper); color: var(--ink); }
.detail-dialog::backdrop { background: rgb(19 43 33 / 65%); }
.dialog-heading { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 18px; }
.dialog-heading .eyebrow { margin: 0; font-size: 9px; }
.dialog-close { width: 32px; height: 32px; border: 1px solid #acb8a4; background: transparent; font-size: 22px; line-height: 1; }
.dialog-close:hover { background: var(--sage); }
/* A layered gallery keeps the dialog size and its three image surfaces stable. */
.detail-images { position: relative; height: 230px; overflow: hidden; }
.detail-images > img { position: absolute; top: 0; left: 0; height: 230px; object-fit: cover; }
.detail-images > img[hidden] { display: block !important; visibility: hidden; }
.dialog-copy { padding: 24px 6px 4px; }
.dialog-copy h2 { margin-bottom: 20px; font-size: 42px; }
.dialog-copy > p { font-size: 14px; color: var(--muted); }
.dialog-facts { display: flex; justify-content: space-between; gap: 12px; padding: 18px 0; margin: 18px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); font-size: 12px; }
.dialog-facts p + p { margin-top: 0; }
.dialog-actions { display: flex; flex-wrap: wrap; gap: 12px; }
.toast { position: fixed; bottom: 22px; left: 24px; right: 24px; z-index: 20; width: auto; max-width: 410px; padding: 14px 20px; border: 1px solid #607252; background: var(--ink); color: var(--paper); box-shadow: 0 6px 24px rgb(36 63 53 / 16%); font-size: 12px; }
.noscript-note { position: fixed; bottom: 0; left: 0; right: 0; padding: 12px 20px; background: var(--ink); color: var(--paper); font-size: 12px; }
@media (max-width: 1040px) {
  .container { padding-left: 32px; padding-right: 32px; }
  h1 { font-size: 60px; }
  h2 { font-size: 46px; }
  .hero-heading { gap: 30px; }
  .hero-figure > img { height: 370px; }
  .stay-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .intro-strip { gap: 25px; }
  .intro-strip > p { font-size: 25px; }
  .story-layout, .booking-layout, .faq-layout, .newsletter-layout { gap: 40px; }
  .story-image img { height: 490px; }
  .booking-intro h2 { font-size: 52px; }
  .booking-form { padding: 24px; }
  .form-row { grid-template-columns: 1fr; gap: 0; }
  .footer-top { gap: 24px; }
}
@media (max-width: 760px) {
  .announcement { font-size: 10px; gap: 14px; }
  .announcement > span { display: none; }
  .header-inner { flex-wrap: wrap; gap: 14px; padding-top: 21px; padding-bottom: 16px; }
  .brand { width: 180px; font-size: 37px; }
  .brand span { font-size: 6px; }
  .main-nav { order: 3; width: 100%; gap: 24px; font-size: 11px; }
  .saved-link { margin-left: auto; font-size: 11px; }
  .hero { padding-top: 42px; }
  .hero-heading { grid-template-columns: 1fr; gap: 24px; }
  h1 { font-size: 56px; }
  .hero-intro { max-width: 430px; }
  .hero-figure > img { height: 320px; }
  .intro-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px; }
  .section { padding-top: 70px; padding-bottom: 70px; }
  .section-heading { grid-template-columns: 1fr; gap: 22px; margin-bottom: 30px; }
  .section-heading > p { max-width: 460px; }
  .filter-bar { flex-wrap: wrap; gap: 16px; padding: 20px; }
  .filter-search { flex-basis: 100%; }
  .filter-region { flex: 1; min-width: 165px; }
  .filter-saved { width: auto; margin-bottom: 12px; }
  .stay-grid { gap: 20px; }
  .stay-content { padding: 18px; }
  .stay-image img { height: 190px; }
  .story-band { padding: 60px 0; }
  .story-layout, .plan-layout, .booking-layout, .faq-layout, .newsletter-layout { grid-template-columns: 1fr; gap: 36px; }
  .story-image img { height: 350px; }
  .story-copy h2 { font-size: 48px; }
  .quote-band { padding: 56px 0; }
  .quote-band p { font-size: 36px; }
  .journal-grid { grid-template-columns: 1fr; gap: 18px; }
  .journal-card { padding: 28px; }
  .journal-card h3 br { display: none; }
  .journal-number { margin-bottom: 18px; }
  .booking-band { padding: 62px 0; }
  .booking-intro { padding-top: 0; }
  .booking-intro h2 { font-size: 52px; }
  .booking-intro > p:not(.eyebrow) { max-width: 470px; }
  .booking-promise { margin-top: 28px; max-width: none; }
  .form-row { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
  .footer-top { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 30px; }
}
@media (max-width: 520px) {
  .container { padding-left: 20px; padding-right: 20px; }
  h1 { font-size: 40px; letter-spacing: -1.2px; }
  h2 { font-size: 38px; letter-spacing: -1px; }
  .hero .eyebrow { font-size: 8px; letter-spacing: 1px; }
  .hero-intro { font-size: 14px; }
  .hero-figure > img { height: 280px; }
  .hero-figure figcaption { left: 15px; bottom: 15px; padding: 13px 14px; max-width: calc(100% - 30px); gap: 14px; }
  .hero-figure figcaption strong { font-size: 16px; }
  .hero-bottom { flex-direction: column; gap: 4px; font-size: 9px; }
  .intro-strip { padding-top: 34px; padding-bottom: 14px; gap: 25px; }
  .intro-strip > p { font-size: 24px; }
  .intro-strip h3 { font-size: 13px; }
  .intro-strip div p { font-size: 11px; }
  .section { padding-top: 60px; padding-bottom: 60px; }
  .filter-bar { padding: 16px; }
  .filter-region { flex-basis: 100%; }
  .filter-saved { margin: 0; }
  .results-line { flex-wrap: wrap; font-size: 10px; }
  .stay-grid { grid-template-columns: 1fr; gap: 24px; }
  .stay-image img { height: 230px; }
  .stay-content { padding: 22px; }
  .stay-content > p { min-height: 0; }
  .amenities { min-height: 0; }
  .stay-meta { font-size: 10px; }
  .story-image img { height: 310px; }
  .story-copy h2 { font-size: 38px; }
  .saved-panel, .note-panel { padding: 22px; }
  .quote-band p { font-size: 28px; }
  .quote-band span { font-size: 8px; letter-spacing: .7px; }
  .booking-intro h2 { font-size: 46px; }
  .booking-form { padding: 22px; }
  .form-heading h3 { font-size: 17px; }
  .form-row { grid-template-columns: 1fr; gap: 0; }
  .price-summary { flex-wrap: wrap; }
  .price-summary output { font-size: 27px; }
  .newsletter-fields { flex-direction: column; }
  .newsletter-fields button { justify-content: space-between; }
  .footer-top { gap: 30px 24px; }
  .footer-top > div:first-child, .footer-note { grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; gap: 6px; }
  .detail-dialog { padding: 18px; }
  .detail-images, .detail-images > img { height: 185px; }
  .dialog-copy { padding-top: 22px; }
  .dialog-copy h2 { font-size: 36px; }
  .dialog-facts { flex-wrap: wrap; }
  .dialog-actions { flex-direction: column; }
  .toast { left: 16px; right: 16px; bottom: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .button, .save-button { transition: none; }
  .button:hover:not(:disabled) { transform: none; }
}

