'use strict';
const byId = id => document.getElementById(id);
let warm = false;
let extraRule = null;
let extraRuleIndex = -1;
const extraSheet = document.createElement('style');
document.head.append(extraSheet);
function showStyle() {
  byId('style-result').textContent = 'Variante: ' + (warm ? 'Sonne' : 'Wald') + '. Zusatzregel: ' + (extraRule ? 'an.' : 'aus.');
}
byId('style-switch').addEventListener('click', () => {
  warm = !warm;
  byId('design-preview').classList.toggle('warm', warm);
  showStyle();
});
byId('rule-switch').addEventListener('click', () => {
  if (extraRule) {
    extraSheet.sheet.deleteRule(extraRuleIndex);
    extraRule = null;
  } else {
    extraRuleIndex = extraSheet.sheet.insertRule('.design-preview { .sample::before { content: "✓ "; color: #a44626; } }', extraSheet.sheet.cssRules.length);
    extraRule = extraSheet.sheet.cssRules[extraRuleIndex];
  }
  showStyle();
});
const picture = byId('landscape');
let evening = false;
let imageVersion = 0;
const imageEvents = [];
function recordImage(kind) {
  imageEvents.push(kind);
  byId('image-events').textContent = 'Ereignisse: ' + imageEvents.slice(-5).join(' → ');
}
picture.addEventListener('load', () => recordImage('load'));
picture.addEventListener('error', () => recordImage('error'));
async function decodePicture() {
  const version = ++imageVersion;
  byId('image-result').textContent = 'Bild wird geladen …';
  try {
    await picture.decode();
    if (version !== imageVersion) return;
    byId('image-result').textContent = 'Dekodiert: ' + picture.naturalWidth + ' × ' + picture.naturalHeight + ' px. complete: ' + picture.complete + '.';
  } catch (error) {
    if (version !== imageVersion) return;
    byId('image-result').textContent = 'Ladefehler: ' + error.name + '. Kein veraltetes Bild als Erfolg gemeldet.';
  }
}
byId('image-switch').addEventListener('click', () => {
  evening = !evening;
  picture.alt = evening ? 'Abendsonne über einer warmen Hügellandschaft' : 'Morgensonne über einer grünen Hügellandschaft';
  picture.src = evening ? 'assets/evening.svg' : 'assets/morning.svg';
  decodePicture();
});
byId('image-error').addEventListener('click', () => {
  picture.src = 'assets/missing.svg';
  decodePicture();
});
decodePicture();
let localFace = null;
byId('font-load').addEventListener('click', async () => {
  const result = byId('font-result');
  result.textContent = 'Schrift wird angefragt …';
  try {
    if (!localFace) localFace = new FontFace('Arial', 'local("Arial")');
    document.fonts.add(localFace);
    await localFace.load();
    byId('font-preview').style.fontFamily = 'Arial, sans-serif';
    await document.fonts.ready;
    result.textContent = 'FontFace: ' + localFace.status + '. FontFaceSet: ' + document.fonts.status + '. Prüfung: ' + document.fonts.check('28px Arial') + '.';
  } catch (error) {
    result.textContent = 'Schrift konnte nicht geladen werden: ' + error.name + '.';
  }
});
byId('data-check').addEventListener('click', () => {
  const source = byId('unicode-input').value;
  const normalized = source.normalize('NFC');
  byId('unicode-result').textContent = 'NFC: ' + normalized + ' (' + source.length + ' → ' + normalized.length + ' UTF-16-Einheiten). NFKC: ' + 'ＡＢＣ ①'.normalize('NFKC') + '.';
  byId('url-result').textContent = new URL('https://bücher.example:443/atelier?q=Café').href;
  const berlin = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
  byId('date-before').textContent = berlin.format(new Date('2026-03-29T00:30:00Z'));
  byId('date-after').textContent = berlin.format(new Date('2026-03-29T01:30:00Z'));
  byId('date-english').textContent = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', dateStyle: 'medium', timeStyle: 'short' }).format(new Date('2026-03-29T01:30:00Z'));
});
const noteKey = 'atelier.browser-foundations.note.v1';
byId('note-save').addEventListener('click', () => {
  try {
    localStorage.setItem(noteKey, byId('note-input').value);
    byId('note-result').textContent = 'Notiz im lokalen Speicher gesetzt. Für den Reload bleibt dieser Schlüssel erhalten.';
  } catch (error) { byId('note-result').textContent = 'Speichern fehlgeschlagen: ' + error.name + '.'; }
});
byId('note-read').addEventListener('click', () => {
  try {
    const note = localStorage.getItem(noteKey);
    if (note === null) byId('note-result').textContent = 'Unter diesem Schlüssel ist keine Notiz gespeichert.';
    else { byId('note-input').value = note; byId('note-result').textContent = 'Gespeicherte Notiz wieder abgerufen.'; }
  } catch (error) { byId('note-result').textContent = 'Abrufen fehlgeschlagen: ' + error.name + '.'; }
});
byId('note-remove').addEventListener('click', () => {
  try { localStorage.removeItem(noteKey); byId('note-result').textContent = 'Nur diese Notiz wurde gelöscht.'; }
  catch (error) { byId('note-result').textContent = 'Löschen fehlgeschlagen: ' + error.name + '.'; }
});

files.styles.css:
:root { color-scheme: light; }
* { box-sizing: border-box; }
body { margin: 0; background: #f5f4ee; color: #203e35; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.55; }
a { color: inherit; text-decoration: none; }
a:hover { color: #a44626; }
.masthead, main, footer { width: calc(100% - 64px); max-width: 1120px; margin: 0 auto; }
.masthead { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 26px 0; border-bottom: 1px solid #c9d0c5; }
.brand { font-size: 26px; font-weight: 700; }
.brand span { font-size: 12px; font-weight: 400; }
nav { display: flex; flex-wrap: wrap; gap: 20px; font-size: 13px; }
.hero { margin: 32px 0; padding: 50px 48px; background: #203e35; color: #f5f4ee; }
.eyebrow { margin: 0 0 12px; color: #a44626; font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; }
.hero .eyebrow { color: #ceddc4; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 24px; font-family: Georgia, serif; font-size: 60px; line-height: 1.08; font-weight: 400; }
.hero p:not(.eyebrow) { max-width: 620px; margin-bottom: 24px; }
.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.card { min-width: 0; padding: 28px; background: white; border: 1px solid #c9d0c5; }
h2 { margin-bottom: 16px; font-size: 28px; line-height: 1.2; }
.card > p:not(.eyebrow):not(.caption):not(.result) { min-height: 75px; }
button, .button { display: inline-block; padding: 11px 15px; border: 1px solid #203e35; background: #203e35; color: white; font-family: inherit; font-size: 14px; cursor: pointer; border-radius: 4px; transition: transform .2s ease, background-color .2s ease, color .2s ease, border-radius .2s ease; }
button:hover, .button:hover { background: #a44626; color: white; transform: translateY(-2px); border-radius: 16px; }
.secondary, .pale { background: #f5f4ee; color: #203e35; }
.actions { display: flex; flex-wrap: wrap; gap: 10px; margin: 18px 0; }
.result { margin: 0; padding: 14px; border-left: 3px solid #9daa8e; background: #edf1e6; overflow-wrap: anywhere; }
.caption { margin: 12px 0 0; color: #617169; font-size: 13px; }
.design-preview { padding: 28px 20px; background: #edf1e6; }
.design-preview {
  .sample { color: #203e35; font-size: 23px; font-weight: 700; }
  .sample::after { content: " / Wald"; font-size: 14px; font-weight: 400; }
  &.warm { background: #f6e6d4; .sample { color: #a44626; } .sample::after { content: " / Sonne"; } }
}
.landscape { display: block; width: 100%; height: auto; aspect-ratio: 2; object-fit: cover; background: #edf1e6; }
.font-preview { min-height: 115px; padding: 20px; border: 1px solid #c9d0c5; font-size: 28px; line-height: 1.3; background: #f5f4ee; }
label { display: block; margin: 12px 0 6px; font-size: 14px; }
input, textarea { display: block; width: 100%; padding: 11px; border: 1px solid #9daa8e; border-radius: 0; background: white; color: #203e35; font-family: inherit; font-size: 16px; }
input:focus-visible, textarea:focus-visible { outline: 2px solid #203e35; outline-offset: 2px; }
code { font-size: 14px; }
.facts { margin: 20px 0 0; font-size: 14px; }
.facts dt { margin-top: 12px; color: #617169; }
.facts dd { margin: 2px 0 0; overflow-wrap: anywhere; }
.wide { grid-column: 1 / -1; }
.wide > p { max-width: 760px; }
.wide > p:not(.eyebrow):not(.caption):not(.result) { min-height: 0; }
.closing { margin: 32px 0; padding: 34px 28px; border: 1px solid #c9d0c5; }
.closing p { max-width: 760px; }
.closing a { border-bottom: 1px solid currentColor; }
footer { display: flex; justify-content: space-between; gap: 16px; padding: 0 0 32px; font-size: 12px; color: #617169; }
@media (max-width: 760px) { .masthead, main, footer { width: calc(100% - 32px); } .masthead { align-items: flex-start; flex-direction: column; gap: 12px; } .hero { padding: 32px 24px; } h1 { font-size: 42px; } .grid { grid-template-columns: minmax(0, 1fr); } .card { padding: 24px; } }
@media (prefers-reduced-motion: reduce) { button, .button { transition: none; } }
